// No serviceWorkerSettings: the Flutter service worker would only unregister
// itself. Offline caching is handled by sw.js (generated by Workbox in CI).
// One CanvasKit variant for every browser, so sw.js precaches a single copy.
_flutter.loader.load({
  config: { canvasKitVariant: 'full' },
});
